-- V1: tabele produktów i klientów oraz sekwencja dla @GeneratedValue encji Product
-- (Hibernate domyślnie szuka sekwencji <tabela>_seq z krokiem 50). Sekwencja startuje od 1001,
-- bo V3 wstawia produkty z jawnymi id 1–14.
create sequence products_seq start with 1001 increment by 50;

create table products (
    id       bigint        not null primary key,
    sku      varchar(20)   not null unique,
    name     varchar(100)  not null,
    category varchar(20)   not null,
    price    numeric(10,2) not null,
    notes    varchar(200)
);

-- Klienci czekają na encję z ćwiczenia 2 lekcji Jpa06FlywayWithJpa. Do tego czasu validate tej tabeli
-- nie sprawdza — sprawdza tylko tabele, które mają encje.
create table customers (
    id        bigint       generated by default as identity primary key,
    full_name varchar(100) not null,
    city      varchar(50),
    email     varchar(255) unique,
    vip       boolean      not null default false
);
